  const openViolations = open.violations.filter((v) => !v.tags.includes('best-practice'));

  console.log(JSON.stringify({
    initialViolations: initialViolations.map((v) => ({ id: v.id, impact: v.impact, targets: v.nodes.map((n) => n.target) })),
    openViolations: openViolations.map((v) => ({ id: v.id, impact: v.impact, targets: v.nodes.map((n) => n.target) })),
    focused,
  }, null, 2));
  await browser.close();
  process.exit(initialViolations.length || openViolations.length ? 1 : 0);
})();
