      const h = (tag, attrs = {}, ...children) => {
        const el = document.createElement(tag);
        for (const [key, value] of Object.entries(attrs)) {
          if (key === "className") {
            el.className = value;
          } else if (key === "text") {
            el.textContent = value;
          } else if (key.startsWith("on") && typeof value === "function") {
            el.addEventListener(key.slice(2).toLowerCase(), value);
          } else if (value !== false && value != null) {
            el.setAttribute(key, value === true ? "" : value);
          }
        }
        for (const child of children.flat()) {
          if (child == null) continue;
          el.append(child.nodeType ? child : document.createTextNode(child));
        }
        return el;
      };

      function ImagePreviewPage() {
        const app = h("main", { id: "main", className: "page" });
        const shell = h("section", { className: "shell", "aria-labelledby": "page-title" });

        const header = h(
          "header",
          { className: "header" },
          h("p", { className: "eyebrow", text: "Library preview" }),
          h("h1", { id: "page-title", text: "Delete image from your library" }),
          h("p", {
            className: "lede",
            text: "Review the image and use the delete button below to confirm removal. The dialog stays closed until you choose to open it.",
          })
        );

        const previewCard = h("article", { className: "preview-card", "aria-label": "Image preview" });
        const media = h(
          "div",
          { className: "preview-media" },
          h("div", { className: "preview-image", role: "img", "aria-label": "Abstract blue and violet landscape preview image" })
        );

        const actions = h(
          "div",
          { className: "meta-row" },
          h(
            "div",
            { className: "title-wrap" },
            h("h2", { text: "Aurora dusk.jpg" }),
            h("p", { text: "Uploaded 2 days ago · 4.8 MB" })
          ),
          h(
            "div",
            { className: "actions" },
            h("button", { type: "button", className: "button trigger", id: "open-dialog", text: "Delete image" })
          )
        );

        const meta = h(
          "div",
          { className: "preview-meta" },
          actions,
          h("p", { className: "help", text: "Deleting removes the file from your library and can't be undone." })
        );

        const status = h("p", {
          className: "status",
          id: "status",
          role: "status",
          "aria-live": "polite",
          "aria-atomic": "true",
        });

        const deletedState = h(
          "div",
          { className: "deleted-state", id: "deleted-state" },
          h("strong", { text: "Image deleted." }),
          " The item has been removed from your library."
        );

        previewCard.append(media, meta, status, deletedState);
        shell.append(header, previewCard);
        app.append(shell);

        const dialog = ConfirmDeleteDialog();
        app.append(dialog);
        return app;
      }

      function ConfirmDeleteDialog() {
        const dialog = h("dialog", {
          id: "confirm-dialog",
          "aria-labelledby": "confirm-title",
          "aria-describedby": "confirm-description",
        });

        const body = h(
          "div",
          { className: "dialog-body" },
          h(
            "div",
            { className: "dialog-header" },
            h(
              "div",
              {},
              h("h2", { id: "confirm-title", text: "Delete this image?" }),
              h("p", {
                id: "confirm-description",
                text: "This will permanently remove Aurora dusk.jpg from your library.",
              })
            ),
            h("button", {
              type: "button",
              className: "close-button",
              "aria-label": "Close dialog",
              text: "×",
              onclick: () => dialog.close("cancel"),
            })
          ),
          h(
            "div",
            { className: "dialog-actions" },
            h("button", {
              type: "button",
              className: "button button-secondary",
              text: "Cancel",
              autofocus: true,
              onclick: () => dialog.close("cancel"),
            }),
            h("button", {
              type: "button",
              className: "button destructive",
              text: "Delete image",
              onclick: () => dialog.close("delete"),
            })
          )
        );

        dialog.append(body);
        return dialog;
      }

      document.getElementById("app").append(ImagePreviewPage());

      const dialog = document.getElementById("confirm-dialog");
      const trigger = document.getElementById("open-dialog");
      const status = document.getElementById("status");
      const previewCard = document.querySelector(".preview-card");

      trigger.addEventListener("click", () => {
        status.textContent = "";
        dialog.showModal();
      });

      dialog.addEventListener("close", () => {
        if (dialog.returnValue === "delete") {
          previewCard.classList.add("is-deleted");
          status.textContent = "Image deleted from your library.";
        } else {
          status.textContent = "Deletion cancelled.";
        }
      });
    </script>
  </body>
</html>
